	);

	wire	[32-1:0]	w_out_real_512;
	wire	[32-1:0]	w_out_img_512;
	wire				w_start_256;
	wire				w_end_256;
	fft_512 fft_512(
		.clk				(		clk			),
		.rst				(		rst			),
		.start				(		w_start_512	),
		.over				(		0	),
		.data_in_real		(		w_out_real_1k),
		.data_in_img		(		w_out_img_1k),
		.data_out_real		(		w_out_real_512),
		.data_out_img		(		w_out_img_512),
		.start_next			(		w_start_256	),
		.end_next			(		w_end_256	)
