	);
	assign start_next  = w_next_level_start;
/*****************<-------Rotators  ------>************************/

	wire		[12:0]		w_rotator_addr;
	wire		[17:0]		w_rotator_real_tmp;
	wire		[17:0]		w_rotator_img_tmp;
	reg			[17:0]		r_rotator_real;
	reg			[17:0]		r_rotator_img;
	wire					w_select;
	Rotator_address #(.layer(5))
	rotator_address_32(
		.clk				(		clk	),
		.rst				(		rst	),
		.rotator_valid		(		w_rotator_valid),
		.rotator_addr		(		w_rotator_addr),
		.select				(		w_select)
	);

rotator_32_real rotator_32_real (
	.clka			(clk),            // input wire clka
	.addra			(w_rotator_addr),          // input wire [8 : 0] addra
	.douta			(w_rotator_real_tmp)         // output wire [17 : 0] douta
);

rotator_32_img rotator_32_img (
	.clka			(clk),            // input wire clka
	.addra			(w_rotator_addr),          // input wire [8 : 0] addra
	.douta			(w_rotator_img_tmp)         // output wire [17 : 0] douta
);
	always@(posedge clk) begin
		if(rst) begin
			r_rotator_real	<= 1 << 16;
			r_rotator_img 	<=0;
		end else begin
			if(w_rotator_valid) begin
				if(w_select) begin
					r_rotator_real	<= 1 << 16;
					r_rotator_img 	<=0;
				end else begin
					r_rotator_real	<= w_rotator_real_tmp;
					r_rotator_img	<= w_rotator_img_tmp;
				end
			end else begin
				r_rotator_real	<= 1 << 16;
				r_rotator_img 	<=0;
			end
		end
	end

/*****************<-------Multiplier------>************************/
	wire		[31:0]		w_out_real_32;
	wire		[31:0]		w_out_img_32;
multiplier multiplier16(
	.a				(	w_D_real),
	.b				(	w_D_img),
	//.ceabcd			(	1),
	.c				(	r_rotator_real),
	.d				(	r_rotator_img),
	.clk			(	clk),
	.rstn			(	~rst),
	.data_real		(	),
	.data_img		(	),
	.data_real_trunc(	w_out_real_32),
	.data_img_trunc	(	w_out_img_32)
);
/*****************<-------output------>************************/
	assign data_out_real  = w_out_real_32;
	assign data_out_img  = w_out_img_32;

endmodule

`timescale 1ns / 1ps
module Rotator16 (
	input			clk,
	input			rst,
	input			rotator_valid,
	output	[17:0]	rotator_real,
	output	[17:0]	rotator_img
);

reg			[3:0]	r_addra		;
reg					select_1d	;
reg					select_2d	;
wire		[17:0]	w_rotator_real_tmp;
wire		[17:0]	w_rotator_img_tmp;

always@(posedge clk) begin
	if(rst) begin
		r_addra <= 0;
	end else begin
		if(rotator_valid) begin
			r_addra		<= r_addra + 1;
		end else begin
			r_addra		<= 0;
		end
	end
end

always@(posedge clk)begin
	if(rst) begin
		select_1d	<=	0;
		select_2d	<=	0;
	end else begin
		select_1d	<=	r_addra[3];
		select_2d	<=	select_1d;
	end
