1	%% first created on 2023.08.24, by Guan Shixun.
2	% implement fft-DIF iteratively.
3	clear;
4	clc;
5	%----------------------------------------> parameters
6	%x = [1 2 -3 -1];
7	%x       = 0:N-1;
8	Fs      = 1000;             % Sampling frequency                    
9	T       = 1/Fs;             % Sampling period
10	N       = 1024;             % Sampling length
11	t       = (0:N-1)*T;          % Sampling time
12	df      = Fs/N;
13	f       = (0:N-1)*df;
14	index   = 0:N-1;
15	%----------------------------------------> generate source
16	noise_pow = 0.2;
17	S = 3*sin(2*pi*50*t) + sin(2*pi*120*t);
18	x = S + noise_pow*randn(size(t));
19	subplot(3,1,1)
20	plot(1000*t(1:100),x(1:100))
21	title("Signal Corrupted with Zero-Mean Random Noise")
22	xlabel("t (milliseconds)")
23	ylabel("X(t)")
24	
25	
26	%----------------------------------------> FFT-DIF
27	%x                   = 0:N-1;
28	levels              = log2(N);
29	X_FFT               = zeros(1,N);
30	X_FFT_middle_result = zeros(levels+1, N);
31	X_FFT_middle_result(1,:) = x;
32	for level = 0:levels-1
33	    len = 2^(levels-level);
34	    mid = len / 2;
35	    Wn  = exp(-1j * 2 * pi / len);
36	    for pos = 1:len:N
37	        for k = 0:mid-1
38	            A = x(pos+k) + x(pos+k+mid);
39	            B = (x(pos+k) - x(pos+k+mid))*Wn^(k);
40	            x(pos+k) = A;
41	            x(pos+k+mid)  = B;
42	        end
43	    end
